// CSS masks and inline SVG use the same geometry. Do not edit the generated CSS.
import { writeFile } from 'node:fs/promises';
import { ICON_PATHS } from '../src/behaviors/icons';
export async function generateIconMasks(): Promise<void> {
  const names = Object.keys(ICON_PATHS) as (keyof typeof ICON_PATHS)[];
  const values = names.map((name) => {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="none" stroke="black" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${ICON_PATHS[name]}"/></svg>`;
    return `  --icen-token-icon-${name}: url("data:image/svg+xml,${encodeURIComponent(svg)}");`;
  });
  await writeFile(new URL('../src/tokens/icon-masks.css',import.meta.url),`/* Generated by scripts/icon-masks.ts from behaviors/icons.ts. */\n:root {\n${values.join('\n')}\n}\n`);
}
if (process.argv[1]?.endsWith('icon-masks.ts')) await generateIconMasks();
